use std::fs

fn find(names: Vec<string>, name: string) -> int {
    let mut r = -1
    for (i, n) in names.enumerate() {
        if n == name { r = i }
    }
    r
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut names: Vec<string> = []
    let mut bals: Vec<int> = []
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().collect()
        if p.len() == 0 { continue }
        let cmd = p[0]
        if cmd == "open" && p.len() >= 3 {
            let amt = p[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if find(names, p[1]) >= 0 {
                println("error: duplicate account")
            } else {
                names.push(p[1])
                bals.push(amt)
                println("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && p.len() >= 3 {
            let amt = p[2].parse::<int>().unwrap_or(0)
            let i = find(names, p[1])
            if amt <= 0 {
                println("error: invalid amount")
            } else if i < 0 {
                println("error: unknown account ${p[1]}")
            } else if cmd == "deposit" {
                bals[i] += amt
                println("ok")
            } else if bals[i] < amt {
                println("error: insufficient funds")
            } else {
                bals[i] -= amt
                println("ok")
            }
        } else if cmd == "transfer" && p.len() >= 4 {
            let amt = p[3].parse::<int>().unwrap_or(0)
            let i = find(names, p[1])
            let j = find(names, p[2])
            if amt <= 0 {
                println("error: invalid amount")
            } else if i < 0 {
                println("error: unknown account ${p[1]}")
            } else if j < 0 {
                println("error: unknown account ${p[2]}")
            } else if i == j {
                println("error: same account")
            } else if bals[i] < amt {
                println("error: insufficient funds")
            } else {
                bals[i] -= amt
                bals[j] += amt
                println("ok")
            }
        } else if cmd == "balance" && p.len() >= 2 {
            let i = find(names, p[1])
            if i < 0 {
                println("error: unknown account ${p[1]}")
            } else {
                println("${bals[i]}")
            }
        }
    }
    let mut order: Vec<string> = []
    for n in names { order.push(n) }
    order.sort()
    for n in order {
        let i = find(names, n)
        println("${n} ${bals[i]}")
    }
}

